namespace ks{namespace{PanelDetectPartialTest partialTest=nullptr;using T=PanelDetectTask;using S=T::Stage;struct Point{unsigned location,length;};Point point(S s){switch(s){case S::ClearPresence:return{0x490,2};case S::WriteClearPresence:return{0x492,6};case S::SetProbeGate:return{0x498,2};case S::WriteProbeGate:return{0x49a,4};case S::SetProbeLatch:return{0x49e,2};case S::WriteProbeLatch:return{0x4a0,2};case S::HoldOuter:return{0x4a2,2};case S::SetOuter:return{0x4a4,4};case S::HoldInner:return{0x4a8,2};case S::SetInner:return{0x4aa,4};case S::TickInner:return{0x4ae,2};case S::RepeatInner:return{0x4b0,2};case S::RestoreInner:return{0x4b2,2};case S::TickOuter:return{0x4b4,2};case S::RepeatOuter:return{0x4b6,2};case S::RestoreOuter:return{0x4b8,2};case S::ReadSense:return{0x4ba,2};case S::MaskSense:return{0x4bc,2};case S::AdmitPresence:return{0x4be,2};case S::SetPresence:return{0x4c0,2};case S::WritePresence:return{0x4c2,6};case S::FinishPresent:return{0x4c8,2};case S::SetIdleLatch:return{0x4ca,2};case S::WriteIdleLatch:return{0x4cc,2};case S::SetIdleGate:return{0x4ce,2};case S::WriteIdleGate:return{0x4d0,4};case S::FinishAbsent:return{0x4d4,2};default:throw std::runtime_error("Invalid panel detect stage");}}}
bool PanelDetectCalls::step(ControllerCpu&h){using namespace controllerDetail;unsigned pc=unsigned(h.getPC());std::optional<Call>*selected=nullptr;for(auto&c:calls)if(c&&c->token-c->depth==h.getSP()){selected=&c;break;}if(pc==0x490){if(selected)throw std::runtime_error("Overlapping panel detect");for(auto&c:calls)if(!c){selected=&c;break;}if(!selected)throw std::runtime_error("Panel detect capacity");selected->emplace(h.getSP());++started;}if(!selected||point((**selected).task.stage()).location!=pc){if(partialTest&&partialTest(h)){++partialEntries;return true;}return false;}auto&t=(**selected).task;auto stage=t.stage();auto before=h.cycles;Boundary f(h,pc,point(stage).length);auto&v=h.regs;auto cost=t.nextClocks();t.advanceBefore(cost,[&]{return uint8_t(h.read8(0xffff5d));},[&](T::Write w,uint8_t value){f.store8(w==T::Write::Presence?0xffec14:w==T::Write::Gate?0xfffebd:0xffff6d,int8_t(value));});auto hold=[&](auto value){f.push(value);(**selected).depth+=sizeof(value);};auto restore=[&](auto&value){f.pop(value);(**selected).depth-=sizeof(value);};switch(stage){case S::ClearPresence:f.move(v[0].rl,0x0);break;case S::SetProbeGate:f.move(v[0].rl,0x1);break;case S::SetProbeLatch:f.move(v[0].rl,0xfffffffe);break;case S::HoldOuter:hold(v[0].r);break;case S::SetOuter:f.move(v[0].r,0x1);break;case S::HoldInner:hold(v[0].r);break;case S::SetInner:f.move(v[0].r,0xa67);break;case S::TickInner:f.inc(v[0].r,-1);break;case S::RestoreInner:restore(v[0].r);break;case S::TickOuter:f.inc(v[0].r,-1);break;case S::RestoreOuter:restore(v[0].r);break;case S::MaskSense:v[0].rl&=0xffffff80;value(h,v[0].rl);break;case S::SetPresence:f.move(v[0].rl,0xffffffff);break;case S::SetIdleLatch:f.move(v[0].rl,0x1);break;case S::SetIdleGate:f.move(v[0].rl,0xffffffff);break;case S::ReadSense:f.move(v[0].rl,t.sense());break;case S::FinishPresent:case S::FinishAbsent:f.ret();h.pc=h.makepc(f.next);selected->reset();++completed;break;default:break;}if(stage!=S::FinishPresent&&stage!=S::FinishAbsent)h.pc=h.makepc(point(t.stage()).location);if(h.cycles-before!=cost)throw std::runtime_error("Panel detect clocks differ");return true;}}

